def bill_covered(payments, bill):
    # True when the payments add up to at least the bill
    paid = sum(payments)
    return round(paid, 2) >= round(bill, 2)

def bill_covered(payments, bill):
    # True when the running total of the payments reaches the bill exactly or goes over it
    paid = sum(payments)
    return round(paid, 2) >= round(bill, 2)

